"""`index.md`: the wiki's orientation, generated by the host after each run, never by the model.

It lists each page as a link with its one-line summary, grouped by type.
"""

from __future__ import annotations

from collections.abc import Iterable
from pathlib import Path

from pa_core.librarian.wiki import INDEX, Page, pages

_GROUPS = (("people", "People"), ("orgs", "Organizations"), ("topics", "Topics"))
"""Each page folder and its heading in the index, in order."""


def render_index(listed: Iterable[Page]) -> str:
    """The index of `listed`: a section per page type that has pages, each page by slug."""
    by_folder: dict[str, list[Page]] = {}
    for page in listed:
        by_folder.setdefault(page.folder, []).append(page)
    parts = ["# Index\n"]
    for folder, heading in _GROUPS:
        group = sorted(by_folder.get(folder, ()), key=lambda page: page.slug)
        if group:
            entries = "".join(f"- [[{page.slug}]]: {page.summary}\n" for page in group)
            parts.append(f"## {heading}\n\n{entries}")
    if len(parts) == 1:
        parts.append("No pages yet.\n")
    return "\n".join(parts)


def write_index(tree: Path) -> None:
    """Regenerates `index.md` in the wiki at `tree` from its pages."""
    (tree / INDEX).write_text(render_index(pages(tree)), encoding="utf-8")
